package org.simpleweather.app;
import android.app.*;
import android.widget.*;
import android.text.*;
import java.time.*;
import java.util.function.Consumer;

/** Direct digit fields only, never the platform clock-face picker. */
final class NumericInputs {
    static EditText number(MainActivity a,LinearLayout row,String label,int value,int digits){LinearLayout col=a.column();col.addView(a.text(label,13,a.MUTED,false));EditText f=new EditText(a);f.setInputType(InputType.TYPE_CLASS_NUMBER);f.setSingleLine(true);f.setSelectAllOnFocus(true);f.setText(String.valueOf(value));f.setTextSize(18);f.setFilters(new InputFilter[]{new InputFilter.LengthFilter(digits)});f.setContentDescription(label);col.addView(f,a.lp(-1,52));if(row.getChildCount()>0)a.gapHorizontal(row,8);row.addView(col,new LinearLayout.LayoutParams(0,-2,1));return f;}
    static void time(MainActivity a,LocalTime initial,Consumer<LocalTime> done){LinearLayout row=a.row();row.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));EditText h=number(a,row,"时（0～23）",initial.getHour(),2),m=number(a,row,"分（0～59）",initial.getMinute(),2);AlertDialog d=new ToolDialog(a).setTitle("输入时间").setView(row).setPositiveButton("确定",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{LocalTime t=LocalTime.of(Integer.parseInt(h.getText().toString()),Integer.parseInt(m.getText().toString()));done.accept(t);d.dismiss();}catch(Exception e){a.toast("请输入 0～23 的小时和 0～59 的分钟");}}));d.show();}
    static void dateTime(MainActivity a,ZonedDateTime initial,Consumer<Instant> done){LinearLayout c=a.column();c.setPadding(a.dp(20),a.dp(12),a.dp(20),a.dp(12));c.addView(a.text("年份范围为 1900～2100；当前时区："+EarthquakeOptions.offset(initial.getZone(),initial.toInstant().toEpochMilli())+"。",13,a.MUTED,false));LinearLayout date=a.row();EditText y=number(a,date,"年",initial.getYear(),4),mo=number(a,date,"月",initial.getMonthValue(),2),day=number(a,date,"日",initial.getDayOfMonth(),2);c.addView(date);LinearLayout time=a.row();EditText h=number(a,time,"时",initial.getHour(),2),mi=number(a,time,"分",initial.getMinute(),2);c.addView(time);AlertDialog d=new ToolDialog(a).setTitle("设置天文时间").setView(c).setPositiveButton("确定",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{int year=Integer.parseInt(y.getText().toString());if(year<1900||year>2100)throw new Exception();LocalDateTime local=LocalDateTime.of(year,Integer.parseInt(mo.getText().toString()),Integer.parseInt(day.getText().toString()),Integer.parseInt(h.getText().toString()),Integer.parseInt(mi.getText().toString()));if(initial.getZone().getRules().getValidOffsets(local).isEmpty()){a.toast("该时刻因夏令时切换而不存在，请选择其他时间");return;}done.accept(local.atZone(initial.getZone()).toInstant());d.dismiss();}catch(Exception e){a.toast("请输入有效的年月日、时和分");}}));d.show();}
}
